package lab

import "encoding/base64"

// nosleepEdit is a bound, not a candidate: sshd with every nanosleep returning at once, which
// takes out OpenSSH's minimum time for each userauth request (auth2.c, ensure_minimum_time_since).
var nosleepEdit = func() Edit {
	so, err := base64.StdEncoding.DecodeString(nosleepSO)
	if err != nil {
		panic(err)
	}
	return Edit{Files: map[string]string{
		"/usr/local/lib/nosleep.so":                         string(so),
		"/etc/systemd/system/ssh.service.d/90-nosleep.conf": "[Service]\nEnvironment=LD_PRELOAD=/usr/local/lib/nosleep.so\n",
	}}
}()

const nosleepSO = ""
